      desc: 'Ολόπλευρη σανίδα SUP, εμπνευσμένη από άγρια ​​φύση, με κορυφαία πολυχρωμία EVA μπλοκ με μοτίβο τσίτα σε παστέλ ροζ, γαλαζοπράσινο και κοραλί.',
