      desc: 'Ολόπλευρη σανίδα SUP εμπνευσμένη από την ανατολική τέχνη με μοτίβα λωτού, koi και λιβελλούλης, με χαραγμένο με λέιζερ μαξιλαράκι έλξης και ντεγκραντέ με ροή νερού.',
